// @ts-ignore -- generated by the isolated pen build.
import moduleUrl from '../../xyo-cpp-wasm/.work/pen-validation-latest/pen-browser.mjs?url'
// @ts-ignore -- generated by the isolated pen build.
import wasmUrl from '../../xyo-cpp-wasm/.work/pen-validation-latest/pen-browser.wasm?url'
import { XyoHeadlessRuntime, type XyoModule } from '../../xyo-cpp-wasm/src/index'
import { createXyoWorkerHost } from '../src/lib/xyo-worker-host'
import { withXyoPenSnapshots } from '../src/lib/xyo-pen-worker-runtime'
import { XyoAudioAbiAdapter } from '../src/lib/xyo-audio-abi-adapter'
import type { XyoWorkerRequest, XyoWorkerResponse } from '../src/lib/xyo-worker-protocol'

const scope = globalThis as unknown as {
  postMessage(response: XyoWorkerResponse): void
  addEventListener(type: 'message', callback: (event: MessageEvent<XyoWorkerRequest>) => void): void
}
const host = createXyoWorkerHost(
  async () => {
    const { default: createModule } = (await import(/* @vite-ignore */ moduleUrl)) as {
      default: (options: { locateFile: (path: string) => string }) => Promise<XyoModule>
    }
    const runtime = new XyoHeadlessRuntime(
      await createModule({ locateFile: (path) => (path.endsWith('.wasm') ? wasmUrl : path) }),
    )
    const pen = runtime.createPenBridge()
    if (!pen) {
      runtime.dispose()
      throw new Error('Isolated pen ABI unavailable')
    }
    const audio = runtime.createAudioBridge()
    const workerRuntime = audio
      ? Object.assign(runtime, { audio: new XyoAudioAbiAdapter(audio, 300) })
      : runtime
    return withXyoPenSnapshots(workerRuntime, pen)
  },
  (response) => scope.postMessage(response),
)
scope.addEventListener('message', (event) => host(event.data))
